(async()=>{const target=document.body.dataset.surface;if(!target)return;const surfaceClass=`surface-${target}`;const response=await fetch('components.html');const html=await response.text();const doc=new DOMParser().parseFromString(html,'text/html');const main=doc.querySelector('main');if(!main)return;main.querySelectorAll('[class]').forEach(el=>{[...el.classList].filter(c=>c.startsWith('surface-')).forEach(c=>el.classList.remove(c));if(el.matches('.component-card,.component-review,.component-cta,.icon-card,.trust-mark,.promo,.component-location,.tabs-panel'))el.classList.add(surfaceClass);if(el.classList.contains('button')){el.classList.remove('button-on-light','button-on-dark');el.classList.add(['primary','secondary','dark'].includes(target)?'button-on-dark':'button-on-light')}});const hero=main.querySelector('.components-hero');if(hero){hero.querySelector('.overline').textContent=`UNA-Elementor / Components Surface QA / ${target}`;hero.querySelector('h1').textContent=`All components on ${target} surface.`;hero.querySelector('.lead').textContent='This QA page forces the complete Components V1 catalog onto one Foundation surface so typography, borders, icons, buttons, states, and supporting text can be audited without page-specific overrides.';const nav=document.createElement('nav');nav.className='components-nav';nav.innerHTML='<a href="components-surface-light.html">Light</a><a href="components-surface-neutral.html">Neutral</a><a href="components-surface-primary.html">Primary</a><a href="components-surface-secondary.html">Secondary</a><a href="components-surface-dark.html">Dark</a>';hero.append(nav)}document.querySelector('#surface-host').replaceWith(main)})().catch(err=>{document.querySelector('#surface-host').textContent=`Surface QA failed to load: ${err.message}`});